"use client";

import { loadFont as loadInstrument } from "@remotion/google-fonts/InstrumentSans";
import { loadFont as loadJetBrains } from "@remotion/google-fonts/JetBrainsMono";
import type React from "react";
import { AbsoluteFill, Easing, interpolate, spring } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import type { GradientParams } from "@/lib/remocn/gsh/gradient-engine";
import { GshGround } from "@/lib/remocn/gsh/gsh-ground";
import type { GshPresetId } from "@/lib/remocn/gsh/presets";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import { type DropUploadElementId, dropUploadTimeline } from "./timeline";

const instrument = loadInstrument("normal", {
  weights: ["400"],
  subsets: ["latin"],
});
const jetbrains = loadJetBrains("normal", {
  weights: ["300", "400"],
  subsets: ["latin"],
});

const ENTER = Easing.bezier(0.32, 0.72, 0, 1);
const EXIT = Easing.bezier(0.55, 0, 1, 0.45);
const FILL = Easing.bezier(0.83, 0, 0.17, 1);
const HEAVY = { mass: 1, damping: 26, stiffness: 120 };
const CARD = { mass: 0.8, damping: 18, stiffness: 160 };
const CHIP = { mass: 0.5, damping: 12, stiffness: 200 };
const MORPH = { damping: 200 };

const ramp = (f: number, start: number, dur: number, easing = ENTER) =>
  interpolate(f, [start, start + dur], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing,
  });

const mix = (a: number, b: number, t: number) => a + (b - a) * t;

// Layout rounds a box and a baseline to whole pixels, so anything eased by
// `left`/`top` clicks along pixel by pixel. Movers below are laid out where
// they land and travel there by transform, dropped once under 1/1000px.
const shift = (dx: number, dy: number) =>
  Math.abs(dx) > 1e-3 || Math.abs(dy) > 1e-3
    ? `translate(${dx}px, ${dy}px) `
    : "";

function FileTile({
  kind,
  accent,
  w,
}: {
  kind: string;
  accent: string;
  w: number;
}) {
  const h = w * 1.26;
  const fold = w * 0.27;
  return (
    <div style={{ position: "relative", width: w, height: h }}>
      <svg
        width={w}
        height={h}
        viewBox={`0 0 ${w} ${h}`}
        style={{ position: "absolute", inset: 0, overflow: "visible" }}
        aria-hidden
      >
        <defs>
          <linearGradient id="du-paper" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor="#ffffff" />
            <stop offset="1" stopColor="#eceef6" />
          </linearGradient>
        </defs>
        <path
          d={`M ${w * 0.1} 0 H ${w - fold} L ${w} ${fold} V ${h - w * 0.1} Q ${w} ${h} ${w * 0.9} ${h} H ${w * 0.1} Q 0 ${h} 0 ${h - w * 0.1} V ${w * 0.1} Q 0 0 ${w * 0.1} 0 Z`}
          fill="url(#du-paper)"
          stroke="rgba(20,24,48,0.1)"
        />
        <path
          d={`M ${w - fold} 0 V ${fold * 0.72} Q ${w - fold} ${fold} ${w - fold * 0.72} ${fold} H ${w} Z`}
          fill="#d7dbea"
        />
        {[0.3, 0.4, 0.5, 0.6].map((y, i) => (
          <rect
            key={y}
            x={w * 0.16}
            y={h * y}
            width={w * (i === 3 ? 0.36 : i === 0 ? 0.4 : 0.62)}
            height={w * 0.045}
            rx={w * 0.022}
            fill={i === 0 ? "#b9bfd6" : "#d9dce8"}
          />
        ))}
      </svg>
      <div
        style={{
          position: "absolute",
          left: w * 0.12,
          bottom: w * 0.12,
          height: w * 0.24,
          padding: `0 ${w * 0.08}px`,
          borderRadius: w * 0.06,
          background: accent,
          color: "#fff",
          fontFamily: jetbrains.fontFamily,
          fontSize: w * 0.15,
          display: "flex",
          alignItems: "center",
          letterSpacing: "0.04em",
          boxShadow: "inset 0 1px 0 rgba(255,255,255,0.3)",
        }}
      >
        {kind}
      </div>
    </div>
  );
}

export interface DropUploadProps {
  theme?: "dark" | "light";
  accent?: string;
  title?: string;
  fileName?: string;
  fileKind?: string;
  fileSize?: string;
  hint?: string;
  history?: { name: string; kind: string; size: string; ago: string }[];
  ground?: GshPresetId;
  groundParams?: Partial<GradientParams>;
  /** Line inside the empty drop zone, before the "browse" link. */
  dropLabel?: string;
  /** Line that replaces it while the file hovers over the zone. */
  releaseLabel?: string;
  /** Status shown once the progress bar fills. */
  doneLabel?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  /** Solid fill in place of the gradient ground; "transparent" drops it. */
  background?: string;
  /** Typeface for the copy. Load it yourself; Instrument Sans by default. */
  fontFamily?: string;
  /** Size of the drop zone and file, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  /**
   * Moves, trims or stretches the zone, the file's flight, hover and drop,
   * the collapse, the upload row and the camera, by the ids in `./timeline`.
   * Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<DropUploadElementId>;
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function DropUpload(props: DropUploadProps) {
  const {
    theme = "dark",
    accent = "#3B5BFD",
    title = "Drop in your launch notes",
    fileName = "launch-notes.md",
    fileKind = "MD",
    fileSize = "2.4 MB",
    hint = "MD, PDF or ZIP · up to 50 MB",
    history = [
      {
        name: "changelog-2.0.pdf",
        kind: "PDF",
        size: "1.1 MB",
        ago: "4 min ago",
      },
      {
        name: "press-kit.zip",
        kind: "ZIP",
        size: "18.6 MB",
        ago: "12 min ago",
      },
    ],
    ground,
    groundParams,
    dropLabel = "Drag and drop a file, or",
    releaseLabel = "Release to upload",
    doneLabel = "Uploaded",
    ink: inkProp,
    background,
    fontFamily = instrument.fontFamily,
    scale = 1,
    delay = 0,
    speed: rate = 1,
    timing,
  } = props;
  const frame = Math.max(0, useSceneFrame() - delay) * rate;
  const { width, height, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    dropUploadTimeline,
    props,
    durationInFrames * rate,
    timing,
  );
  const cam = tl.get("camera");
  const zoneEl = tl.get("zone");
  const titleEl = tl.get("title");
  const fly = tl.get("fly");
  const hover = tl.get("hover");
  const dropEl = tl.get("drop");
  const collapseEl = tl.get("collapse");
  const infoEl = tl.get("info");
  const progressEl = tl.get("progress");
  const doneEl = tl.get("done");
  const dark = theme === "dark";
  const portrait = height > width * 1.2;
  const stageW = portrait ? 760 : 1280;
  const stageH = portrait ? 1351 : 720;
  const sc = width / stageW;

  const ink = inkProp ?? (dark ? "#f1f2fb" : "#151824");
  const soft = dark ? "rgba(225,228,250,0.7)" : "rgba(21,24,36,0.66)";
  const muted = dark ? "rgba(225,228,250,0.46)" : "rgba(21,24,36,0.44)";
  const dash = dark ? "rgba(225,228,250,0.34)" : "rgba(21,24,36,0.26)";
  const base = dark ? "#11141f" : "#ffffff";
  const rowShadow = (k: number) =>
    dark
      ? `0 0 0 1px rgba(255,255,255,${0.08 * k}), 0 40px 90px -24px rgba(0,2,14,${0.7 * k})`
      : `0 0 0 1px rgba(20,24,48,${0.07 * k}), 0 1px 3px rgba(20,24,48,${0.06 * k}), 0 36px 80px -24px rgba(20,30,70,${0.22 * k})`;
  const accentMix = (pct: number, base: string) =>
    `color-mix(in oklab, ${accent} ${pct}%, ${base})`;

  const zoneW = portrait ? 564 : 760;
  const zoneH = portrait ? 440 : 320;
  const rowW = portrait ? 564 : 760;
  const rowH = 104;
  const cx = stageW / 2;
  const cy = portrait ? 640 : 412;
  const titleSize = portrait ? 50 : 60;
  const titleGap = portrait ? 56 : 44;

  const zoneIn = spring({ frame: frame - zoneEl.start, fps, config: HEAVY });
  const titleIn = ramp(frame, titleEl.start, titleEl.length);
  const collapse = spring({
    frame: frame - collapseEl.start,
    fps,
    config: MORPH,
  });
  const highlight =
    ramp(
      frame,
      hover.start + hover.beat("highlightAt"),
      hover.beat("highlight"),
    ) *
    (1 - ramp(frame, collapseEl.start, collapseEl.beat("highlightOut"), EXIT));
  const breathe =
    Math.sin(((frame - hover.start) / 22) * Math.PI * 2) * 0.012 * highlight;
  const dropHit = spring({
    frame: frame - dropEl.start - dropEl.beat("hitAt"),
    fps,
    config: CHIP,
  });
  const dropPunch =
    0.03 *
    Math.sin(Math.PI * Math.min(1, dropHit)) *
    (1 -
      ramp(
        frame,
        dropEl.start + dropEl.beat("punchOutAt"),
        dropEl.beat("punchOut"),
      ));

  const solid = ramp(
    frame,
    collapseEl.start + collapseEl.beat("solidAt"),
    collapseEl.beat("solid"),
  );
  const tint = accentMix(Math.round(12 * highlight), "transparent");
  const radius = mix(24, 20, collapse);
  const zW = mix(zoneW, rowW, collapse);
  const zH = mix(zoneH, rowH, collapse);
  const zL = cx - zW / 2;
  const zT = cy - zH / 2;

  const startX = portrait ? cx + 260 : cx + 560;
  const startY = portrait ? cy + 600 : cy + 360;
  const ctrlX = portrait ? cx + 300 : cx + 300;
  const ctrlY = portrait ? cy - 200 : cy - 300;
  const hoverX = cx + 30;
  const hoverY = cy - (portrait ? 84 : 66);
  const flyT = (f: number) =>
    spring({
      frame: f - fly.start,
      fps,
      config: CARD,
      durationInFrames: fly.length,
    });
  const bez = (t: number, a: number, c: number, b: number) =>
    (1 - t) * (1 - t) * a + 2 * (1 - t) * t * c + t * t * b;
  const p = flyT(frame);
  const pPrev = flyT(frame - 1);
  let tx = bez(p, startX, ctrlX, hoverX);
  let ty = bez(p, startY, ctrlY, hoverY);
  const speed = Math.hypot(
    tx - bez(pPrev, startX, ctrlX, hoverX),
    ty - bez(pPrev, startY, ctrlY, hoverY),
  );
  const hoverAmt =
    ramp(frame, hover.start + hover.beat("swayAt"), hover.beat("sway")) *
    (1 - ramp(frame, dropEl.start, dropEl.beat("fall")));
  tx += Math.sin((frame - hover.start) / 7) * 5 * hoverAmt;
  ty += Math.cos((frame - hover.start) / 9) * 5 * hoverAmt;
  let rot =
    mix(28, -7, p) + Math.sin((frame - hover.start) / 10) * 2.5 * hoverAmt;
  let lift = mix(1.2, 0.74, p);
  const drop = ramp(frame, dropEl.start, dropEl.beat("fall"), EXIT);
  lift *= mix(1, 0.84, drop);
  ty += 16 * drop;
  rot = mix(rot, -3, drop);
  const tileW = 112;
  const iconW = 48;
  const iconX = cx - rowW / 2 + 26 + iconW / 2;
  const iconY = cy;
  const toRow = spring({
    frame: frame - collapseEl.start - collapseEl.beat("toRowAt"),
    fps,
    config: MORPH,
  });
  tx = mix(tx, iconX, toRow);
  ty = mix(ty, iconY, toRow);
  rot = mix(rot, 0, toRow);
  const tileScale = mix(lift, iconW / tileW, toRow);
  const tileBlur = Math.min(6, speed * 0.1);
  const shadowAmt = (1 - drop * 0.7) * (1 - toRow);

  const zoneContent =
    1 -
    ramp(
      frame,
      collapseEl.start + collapseEl.beat("contentAt"),
      collapseEl.beat("contentOut"),
      EXIT,
    );
  const info = ramp(frame, infoEl.start, infoEl.length);
  const prog = interpolate(frame, [progressEl.start, progressEl.end], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: FILL,
  });
  const done = spring({ frame: frame - doneEl.start, fps, config: CHIP });
  const doneIn = ramp(frame, doneEl.start, doneEl.length);
  const pct = Math.round(prog * 100);

  const camIn = spring({ frame: frame - cam.start, fps, config: HEAVY });
  const rowFocus = spring({
    frame: frame - collapseEl.start,
    fps,
    config: HEAVY,
  });
  const rotX = mix(18, 4, camIn) - 2.5 * rowFocus;
  const rotY = mix(14, 4, camIn) - 4 * rowFocus;
  const push =
    mix(0.9, 1, camIn) +
    0.025 *
      ramp(
        frame,
        cam.start + cam.beat("pushAt"),
        cam.beat("push"),
        Easing.linear,
      ) +
    (portrait ? 0.06 : 0.26) * rowFocus;
  const titleTop0 = cy - zoneH / 2 - titleGap - titleSize * 1.05;
  const titleTop1 = cy - rowH / 2 - (portrait ? 44 : 34) - titleSize * 1.05;
  const titleTop = mix(titleTop0, titleTop1, rowFocus);
  const histH = 84;
  const histGap = 14;
  const shown = portrait ? history : [];
  const listBottom = cy + rowH / 2 + shown.length * (histH + histGap);
  const groupMid = (titleTop1 + listBottom) / 2;
  const camY = rowFocus * (groupMid - cy) * 0.9;

  const resolvedGround: GshPresetId =
    ground ?? (dark ? "earthshine" : "paper-crease");
  const resolvedParams =
    groundParams ??
    (dark
      ? undefined
      : {
          colors: ["#9db8e6", "#d4e1f4", "#eef2f8", "#2c4f9e"],
          background: "#f1f3f6",
        });

  return (
    <AbsoluteFill style={{ fontFamily, overflow: "hidden" }}>
      {background === undefined ? (
        <GshGround
          preset={resolvedGround}
          params={resolvedParams}
          timeOffset={2}
          timeScale={0.5}
        />
      ) : (
        <AbsoluteFill
          style={{
            background: background === "transparent" ? undefined : background,
          }}
        />
      )}
      <ScaleLayer scale={scale}>
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: stageW,
            height: stageH,
            transform: `scale(${sc})`,
            transformOrigin: "0 0",
            perspective: 2000,
          }}
        >
          <div
            style={{
              position: "absolute",
              inset: 0,
              transformStyle: "preserve-3d",
              transformOrigin: `${cx}px ${cy}px`,
              transform: `translateY(${-camY * push}px) scale(${push}) rotateX(${rotX}deg) rotateY(${rotY}deg)`,
            }}
          >
            <div
              style={{
                position: "absolute",
                left: 40,
                right: 40,
                top: titleTop1,
                height: titleSize * 1.25,
                transform: shift(0, titleTop - titleTop1) || undefined,
                overflow: "hidden",
                textAlign: "center",
              }}
            >
              <div
                style={{
                  fontSize: titleSize,
                  lineHeight: 1.15,
                  letterSpacing: "-0.035em",
                  fontWeight: 400,
                  color: ink,
                  transform: `translateY(${mix(105, 0, titleIn)}%)`,
                }}
              >
                {title}
              </div>
            </div>

            <div
              style={{
                position: "absolute",
                left: cx - rowW / 2,
                top: cy - rowH / 2,
                width: zW,
                height: zH,
                borderRadius: radius,
                background: `linear-gradient(${tint}, ${tint}), color-mix(in oklab, ${base} ${Math.round(mix(dark ? 58 : 52, 100, solid))}%, transparent)`,
                boxShadow: rowShadow(solid),
                opacity: ramp(
                  frame,
                  zoneEl.start + zoneEl.beat("fadeAt"),
                  zoneEl.beat("fade"),
                ),
                transform: `${shift(zL - (cx - rowW / 2), zT - (cy - rowH / 2))}translateY(${mix(60, 0, zoneIn)}px) scale(${mix(0.94, 1, zoneIn) * (1 + breathe + dropPunch)})`,
                overflow: "hidden",
              }}
            >
              <svg
                width={zW}
                height={zH}
                style={{ position: "absolute", inset: 0, opacity: zoneContent }}
                aria-hidden
              >
                <rect
                  x={0.75}
                  y={0.75}
                  width={Math.max(0, zW - 1.5)}
                  height={Math.max(0, zH - 1.5)}
                  rx={radius - 0.75}
                  fill="none"
                  stroke={
                    highlight > 0.02
                      ? accentMix(Math.round(85 * highlight), dash)
                      : dash
                  }
                  strokeWidth={1.5}
                  strokeDasharray="9 7"
                  strokeDashoffset={-frame * 0.7 * (0.25 + highlight)}
                />
              </svg>
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  justifyContent: "center",
                  gap: 14,
                  opacity: zoneContent,
                  transform: `translateY(${36 * highlight}px) scale(${mix(0.94, 1, zoneContent)})`,
                }}
              >
                <div
                  style={{
                    width: 44,
                    height: 44,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    transform: `scale(${mix(1, 0.6, highlight)})`,
                    opacity: 1 - highlight,
                  }}
                >
                  <svg viewBox="0 0 24 24" width={34} height={34} aria-hidden>
                    <path
                      d="M12 15V4M7.5 8.5 12 4l4.5 4.5M5 14v4.5A1.5 1.5 0 0 0 6.5 20h11a1.5 1.5 0 0 0 1.5-1.5V14"
                      fill="none"
                      stroke={soft}
                      strokeWidth={1.5}
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                </div>
                <div
                  style={{
                    position: "relative",
                    height: 28,
                    width: zW - 60,
                    textAlign: "center",
                  }}
                >
                  <div
                    style={{
                      position: "absolute",
                      inset: 0,
                      fontSize: 21,
                      color: ink,
                      letterSpacing: "-0.01em",
                      opacity: 1 - highlight,
                      transform: `translateY(${-8 * highlight}px)`,
                    }}
                  >
                    {dropLabel}{" "}
                    <span
                      style={{
                        color: dark ? accentMix(50, "#ffffff") : accent,
                        textDecoration: "underline",
                        textUnderlineOffset: 4,
                        textDecorationThickness: 1,
                      }}
                    >
                      browse
                    </span>
                  </div>
                  <div
                    style={{
                      position: "absolute",
                      inset: 0,
                      fontSize: 21,
                      color: dark ? "#ffffff" : accent,
                      opacity: highlight,
                      transform: `translateY(${8 * (1 - highlight)}px)`,
                    }}
                  >
                    {releaseLabel}
                  </div>
                </div>
                <div
                  style={{
                    fontFamily: jetbrains.fontFamily,
                    fontSize: 17,
                    color: muted,
                  }}
                >
                  {hint}
                </div>
              </div>

              <div
                style={{
                  position: "absolute",
                  left: 26 + iconW + 20,
                  right: 26,
                  top: 0,
                  height: rowH,
                  opacity: info,
                  display: frame >= infoEl.start ? "block" : "none",
                }}
              >
                <div
                  style={{
                    position: "absolute",
                    left: 0,
                    right: 64,
                    top: 24,
                    display: "flex",
                    alignItems: "baseline",
                    gap: 12,
                    transform: `translateY(${mix(12, 0, info)}px)`,
                  }}
                >
                  <span
                    style={{
                      fontSize: 21,
                      color: ink,
                      letterSpacing: "-0.01em",
                    }}
                  >
                    {fileName}
                  </span>
                  <span
                    style={{
                      fontFamily: jetbrains.fontFamily,
                      fontSize: 17,
                      color: muted,
                    }}
                  >
                    {fileSize}
                  </span>
                  <div style={{ flex: 1 }} />
                  <span
                    style={{
                      position: "relative",
                      fontSize: 17,
                      color: soft,
                      width: 110,
                      textAlign: "right",
                    }}
                  >
                    <span
                      style={{
                        position: "absolute",
                        right: 0,
                        opacity: 1 - doneIn,
                      }}
                    >
                      Uploading
                    </span>
                    <span
                      style={{
                        position: "absolute",
                        right: 0,
                        color: dark ? accentMix(45, "#ffffff") : accent,
                        opacity: doneIn,
                        transform: `translateY(${mix(8, 0, doneIn)}px)`,
                      }}
                    >
                      {doneLabel}
                    </span>
                  </span>
                </div>
                <div
                  style={{
                    position: "absolute",
                    left: 0,
                    right: 64,
                    top: 64,
                    height: 6,
                    borderRadius: 3,
                    background: dark
                      ? "rgba(255,255,255,0.08)"
                      : "rgba(20,24,48,0.07)",
                    overflow: "hidden",
                  }}
                >
                  <div
                    style={{
                      width: `${prog * 100}%`,
                      height: "100%",
                      borderRadius: 3,
                      background: accent,
                    }}
                  />
                </div>
                <div
                  style={{
                    position: "absolute",
                    right: 0,
                    top: (rowH - 40) / 2,
                    width: 40,
                    height: 40,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                  }}
                >
                  <span
                    style={{
                      position: "absolute",
                      fontFamily: jetbrains.fontFamily,
                      fontSize: 17,
                      color: muted,
                      opacity: 1 - doneIn,
                      fontVariantNumeric: "tabular-nums",
                    }}
                  >
                    {pct}%
                  </span>
                  <div
                    style={{
                      width: 40,
                      height: 40,
                      borderRadius: 20,
                      background: accent,
                      boxShadow: "inset 0 1px 0 rgba(255,255,255,0.25)",
                      transform: `scale(${done})`,
                      opacity: doneIn,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                    }}
                  >
                    <svg viewBox="0 0 24 24" width={22} height={22} aria-hidden>
                      <path
                        d="m6 12.5 4 4 8-9"
                        fill="none"
                        stroke="#fff"
                        strokeWidth={2.2}
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeDasharray={20}
                        strokeDashoffset={
                          20 *
                          (1 -
                            ramp(
                              frame,
                              doneEl.start + doneEl.beat("checkAt"),
                              doneEl.beat("check"),
                            ))
                        }
                      />
                    </svg>
                  </div>
                </div>
              </div>
            </div>

            {shown.map((h, i) => {
              const at =
                infoEl.start +
                infoEl.beat("historyAt") +
                i * infoEl.beat("stagger");
              const k = spring({ frame: frame - at, fps, config: CARD });
              return (
                <div
                  key={h.name}
                  style={{
                    position: "absolute",
                    left: cx - rowW / 2,
                    top: cy + rowH / 2 + histGap + i * (histH + histGap),
                    width: rowW,
                    height: histH,
                    borderRadius: 20,
                    background: base,
                    boxShadow: rowShadow(0.55),
                    display: "flex",
                    alignItems: "center",
                    gap: 20,
                    padding: "0 26px 0 32px",
                    opacity: ramp(frame, at, infoEl.beat("history")),
                    transform: `translateY(${mix(28, 0, k)}px)`,
                  }}
                >
                  <FileTile kind={h.kind} accent={accent} w={38} />
                  <span
                    style={{
                      fontSize: 21,
                      color: ink,
                      letterSpacing: "-0.01em",
                    }}
                  >
                    {h.name}
                  </span>
                  <span
                    style={{
                      fontFamily: jetbrains.fontFamily,
                      fontSize: 17,
                      color: muted,
                    }}
                  >
                    {h.size}
                  </span>
                  <div style={{ flex: 1 }} />
                  <span style={{ fontSize: 17, color: muted }}>{h.ago}</span>
                </div>
              );
            })}

            <div
              style={{
                position: "absolute",
                left: iconX - tileW / 2,
                top: iconY - (tileW * 1.26) / 2,
                transform: `${shift(tx - iconX, ty - iconY)}rotate(${rot}deg) scale(${tileScale})`,
                filter: [
                  tileBlur > 0.3 ? `blur(${tileBlur}px)` : "",
                  `drop-shadow(0 ${mix(4, 34, shadowAmt)}px ${mix(6, 36, shadowAmt)}px rgba(4,6,30,${dark ? 0.55 : 0.22}))`,
                ].join(" "),
                opacity: ramp(frame, fly.start, fly.beat("fade")),
              }}
            >
              <FileTile kind={fileKind} accent={accent} w={tileW} />
            </div>
          </div>
        </div>
      </ScaleLayer>
    </AbsoluteFill>
  );
}

