  },
  {
    id: "hover",
    lane: "File",
    label: "hover",
    start: B.hover,
    length: B.drop - B.hover,
    follows: "fly",
    beats: { highlightAt: -8, highlight: 12, swayAt: -4, sway: 10 },
  },
  {
    id: "drop",
    lane: "File",
    label: "drop",
    start: B.drop,
    length: B.collapse - B.drop,
